source='''from collections import deque


def transform(grid):
    h, w = len(grid), len(grid[0])
    outside = [[False] * w for _ in range(h)]
    q = deque()
    for r in range(h):
        for c in (0, w - 1):
            if grid[r][c] == 0 and not outside[r][c]:
                outside[r][c] = True
                q.append((r, c))
    for c in range(w):
        for r in (0, h - 1):
            if grid[r][c] == 0 and not outside[r][c]:
                outside[r][c] = True
                q.append((r, c))
    while q:
        r, c = q.popleft()
        for nr, nc in ((r - 1, c), (r + 1, c), (r, c - 1), (r, c + 1)):
            if 0 <= nr < h and 0 <= nc < w and grid[nr][nc] == 0 and not outside[nr][nc]:
                outside[nr][nc] = True
                q.append((nr, nc))

    seen = [row[:] for row in outside]
    out = [row[:] for row in grid]
    colors = {(3, 3): 8, (5, 5): 4, (7, 7): 3}
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 0 or seen[r][c]:
                continue
            seen[r][c] = True
            q.append((r, c))
            component = []
            while q:
                rr, cc = q.popleft()
                component.append((rr, cc))
                for nr, nc in ((rr - 1, cc), (rr + 1, cc), (rr, cc - 1), (rr, cc + 1)):
                    if 0 <= nr < h and 0 <= nc < w and grid[nr][nc] == 0 and not seen[nr][nc]:
                        seen[nr][nc] = True
                        q.append((nr, nc))
            min_r = min(rr for rr, _ in component)
            max_r = max(rr for rr, _ in component)
            min_c = min(cc for _, cc in component)
            max_c = max(cc for _, cc in component)
            color = colors.get((max_r - min_r + 1, max_c - min_c + 1))
            if color is not None:
                for rr, cc in component:
                    out[rr][cc] = color
    return out
